import React from 'react';
import { QuestionLayout } from '../ui/QuestionLayout';
import OptionChipGroup from '../ui/OptionChipGroup';
import {
  MiniFormInjurySporting,
  MiniFormInjuryTripFall,
  MiniFormInjuryTraffic,
  MiniFormInjuryAttack,
} from '../ui/MiniFormInjury';
import { useClaim } from '@/context/ClaimContext';
import type { InjuryType } from '../../types/claim';

const INJURY_OPTIONS: { label: string; value: InjuryType; description: string }[] = [
  { label: 'Yes', value: 'sporting', description: 'one of these applies to me' },
  { label: 'No', value: 'other', description: 'none of these describe my situation' },
];

export const Step7HowHappened: React.FC = () => {
  const { state, dispatch } = useClaim();

  const handleSelect = (value: InjuryType) => {
    dispatch({
      type: 'UPDATE_FIELD',
      payload: {
        field: 'injuryDetails',
        value: { type: value },
      },
    });
  };

  const handleInjuryChange = (updates: Partial<any>) => {
    const current = (state.responses.injuryDetails as any) || { type: null };
    dispatch({
      type: 'UPDATE_FIELD',
      payload: {
        field: 'injuryDetails',
        value: { ...current, ...updates },
      },
    });
  };

  const injuryDetails = (state.responses.injuryDetails as any) || { type: null };
  const type = injuryDetails.type;

  return (
    <QuestionLayout
      partLabel="Background details"
      currentIndex={1}
      total={2}
      question={
        <>
          Is your condition the result of a sporting injury, a traffic accident,
          <br />
          a trip/fall, or an attack/assault?
        </>
      }
    >
      {/* Show OptionChipGroup unless a mini form is active */}
      {(!type || type === 'other') && (
        <OptionChipGroup
          options={INJURY_OPTIONS}
          value={type}
          onChange={handleSelect}
          layout="grid"
        />
      )}

      {type === 'sporting' && (
        <MiniFormInjurySporting injuryDetails={injuryDetails} onChange={handleInjuryChange} />
      )}
      {type === 'trip_fall' && (
        <MiniFormInjuryTripFall injuryDetails={injuryDetails} onChange={handleInjuryChange} />
      )}
      {type === 'traffic' && (
        <MiniFormInjuryTraffic injuryDetails={injuryDetails} onChange={handleInjuryChange} />
      )}
      {type === 'attack' && (
        <MiniFormInjuryAttack injuryDetails={injuryDetails} onChange={handleInjuryChange} />
      )}
    </QuestionLayout>
  );
};

export default Step7HowHappened;
